+const IDENT = "[0-9A-Za-z-]+";
+const VERSION_RE = new RegExp(
+  `^(\\d+)\\.(\\d+)\\.(\\d+)(?:-(${IDENT}(?:\\.${IDENT})*))?(?:\\+(${IDENT}(?:\\.${IDENT})*))?$`,
+);
+const NUMERIC_RE = /^\d+$/;
+
 /** Parse a version string. See README.md for the accepted syntax. */
 export function parseVersion(text: string): Version {
-  throw new Error("not implemented");
+  const trimmed = text.trim();
+  const body = trimmed.startsWith("v") ? trimmed.slice(1) : trimmed;
+  const match = VERSION_RE.exec(body);
+  if (match === null) {
+    throw new Error(`invalid version: ${JSON.stringify(text)}`);
+  }
+  const [, major, minor, patch, pre] = match;
+  return {
+    major: Number(major),
+    minor: Number(minor),
+    patch: Number(patch),
+    prerelease: pre === undefined ? [] : pre.split("."),
+  };
+}
+
+/** Compare two numeric strings without losing precision on large values. */
+function compareNumericStrings(a: string, b: string): -1 | 0 | 1 {
+  const x = a.replace(/^0+(?=\d)/, "");
+  const y = b.replace(/^0+(?=\d)/, "");
+  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
+  if (x === y) return 0;
+  return x < y ? -1 : 1;
+}
